mapper.select:
select
    c.id, c.order_id, c.user_id, c.parent_id, c.reply_user_id, c.content,
    c.like_count, c.create_time,
    u.nick_name as user_nick_name,
    u.avatar    as user_avatar
from apply_comment c
left join app_user u on u.id = c.user_id and u.del_flag = '0'
where c.del_flag = '0'

    and c.id = #{bo.id}


    and c.order_id = #{bo.orderId}


    and c.user_id = #{bo.userId}


    and c.content like concat('%', #{bo.keyword}, '%')


    and c.create_time >= #{bo.beginTime}


    and c.create_time <= #{bo.endTime}

order by c.create_time desc
